import { Radio, RadioProps, SIZE } from '@ds/toggles';
import { Meta, StoryObj } from '@storybook/react';

import { StoryTable } from '#storybook/components';

import styles from './styles.module.scss';

const meta: Meta<RadioProps> = {
  title: 'Snack/Inputs & Forms/Toggles/Radio', id: 'components-toggles-radio',
  component: Radio,
  parameters: { layout: 'centered' },
  args: {
    size: 'xs',
    checked: false,
    loading: false,
    disabled: false,
  },
};

export default meta;

type Story = StoryObj<RadioProps>;

const sizes = Object.values(SIZE);

export const VisualMatrix: Story = {
  tags: ['dev', 'test'],
  parameters: { controls: { disable: true } },
  render: () => (
    <div className={styles.wrapper}>
      {sizes.map(size => (
        <StoryTable
          key={size}
          sectionTitle={`States (Size ${size})`}
          firstColumnHeader=''
          columnHeaders={['unchecked', 'checked']}
          rows={[
            {
              variantLabel: 'Regular',
              cells: [<Radio key={'unchecked'} size={size} />, <Radio key={'checked'} checked size={size} />],
            },
            {
              variantLabel: 'Disabled',
              cells: [
                <Radio key={'unchecked'} disabled size={size} />,
                <Radio key={'checked'} checked disabled size={size} />,
              ],
            },
            {
              variantLabel: 'Load',
              cells: [<Radio key={'unchecked'} loading size={size} />],
            },
          ]}
        />
      ))}
    </div>
  ),
};
